Fixpoint kw_find (k : list kentry) (b : expr) (off : Z) (w : nat) : option expr :=
  match k with
  | [] => None
  | KWord (SA b' o') w' v :: r => if (expr_eqb b' b && Z.eqb o' off && Nat.eqb w' w)%bool then Some v else kw_find r b off w
  | _ :: r => kw_find r b off w
  end.

